"""Compare tables regenerated by the added audits with the frozen reference tables in reference_results/.

    python verify_extra.py --group improvement   # strong baselines, normal-condition sensitivity
    python verify_extra.py --group official      # audits that read the official pipeline outputs

The table list is fixed in package_manifest.json (extra_reference_tables). Reference tables never replace
computed results; this script only checks that a fresh run regenerates the same values.
"""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

import pandas as pd

ROOT = Path(__file__).resolve().parent


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--group", choices=("improvement", "official"), required=True)
    args = parser.parse_args()
    manifest = json.loads((ROOT / "package_manifest.json").read_text(encoding="utf-8"))
    tables = [item for item in manifest.get("extra_reference_tables", []) if item["group"] == args.group]
    assert tables, f"No reference tables declared for group {args.group}"
    checks = []
    for item in tables:
        reference, generated = ROOT / item["reference"], ROOT / item["generated"]
        assert generated.is_file(), f"Missing regenerated table: {item['generated']}"
        expected, actual = pd.read_csv(reference), pd.read_csv(generated)
        pd.testing.assert_frame_equal(actual, expected, check_dtype=False, check_exact=False, rtol=1e-9, atol=1e-11)
        checks.append(dict(table=item["generated"], rows=len(actual), passed=True,
                           reference_sha256=hashlib.sha256(reference.read_bytes()).hexdigest()))
    result = dict(passed=True, group=args.group, tables=len(checks), rows=sum(c["rows"] for c in checks),
                  rtol=1e-9, atol=1e-11, checks=checks)
    target = ROOT / "logs" / f"extra_reference_{args.group}.json"
    target.parent.mkdir(exist_ok=True)
    target.write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(dict(passed=True, group=args.group, tables=len(checks), rows=result["rows"]), ensure_ascii=False))


if __name__ == "__main__":
    main()
